<?php require 'includes/auth.php';require_role('buyer');$id=(int)($_GET['id']??0);$pdo=db();$s=$pdo->prepare('SELECT * FROM orders WHERE id=? AND buyer_id=?');$s->execute([$id,user()['id']]);$o=$s->fetch();if(!$o){flash('error','Order not found.');redirect('orders.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(post('action')==='cancel'&&$o['status']==='Pending'){try{$pdo->beginTransaction();$items=$pdo->prepare('SELECT oi.product_id,oi.quantity FROM order_items oi JOIN seller_orders so ON so.id=oi.seller_order_id WHERE so.order_id=?');$items->execute([$id]);foreach($items as $item)if($item['product_id'])$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$item['quantity'],$item['product_id']]);$pdo->prepare("UPDATE orders SET status='Cancelled' WHERE id=? AND buyer_id=?")->execute([$id,user()['id']]);$pdo->prepare("UPDATE seller_orders SET status='Cancelled' WHERE order_id=?")->execute([$id]);$pdo->commit();flash('success','Order cancelled and stock restored.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Could not cancel this order.');}redirect('order-details.php?id='.$id);}}$s=$pdo->prepare('SELECT so.*,sp.shop_name FROM seller_orders so JOIN seller_profiles sp ON so.seller_id=sp.id WHERE so.order_id=?');$s->execute([$id]);$sellerOrders=$s->fetchAll();$stages=['Pending'=>'Order placed','Accepted'=>'Confirmed','Preparing'=>'Preparing','Ready for Pickup'=>'Ready for pickup','Out for Delivery'=>'Out for delivery','Delivered'=>'Delivered'];$current=array_search($o['status'],array_keys($stages),true);$pageTitle='Order '.$o['order_number'];require 'includes/header.php';?><div class="page-title"><p class="eyebrow">ORDER <?=e($o['order_number'])?></p><h1>Track your order</h1><span class="badge <?=status_class($o['status'])?>"><?=e($o['status'])?></span></div><?php if($o['status']!=='Cancelled'):?><div class="order-track"><?php $n=0;foreach($stages as $status=>$label):?><span class="<?=$current!==false&&$n<=$current?'active':''?>"><?=$current!==false&&$n<=$current?'✓ ':''?><?=e($label)?></span><?php $n++;endforeach;?></div><?php endif;?><div class="checkout"><section><?php foreach($sellerOrders as $so):$it=$pdo->prepare('SELECT * FROM order_items WHERE seller_order_id=?');$it->execute([$so['id']]);?><div class="order-seller"><h2><?=e($so['shop_name'])?> <span class="badge <?=status_class($so['status'])?>"><?=e($so['status'])?></span></h2><?php foreach($it as $i):?><p><?=e($i['product_name'])?> <span><?=$i['quantity']?> kg × ₹<?=number_format($i['unit_price'],2)?></span><strong>₹<?=number_format($i['line_total'],2)?></strong></p><?php endforeach;?></div><?php endforeach;?></section><aside class="summary"><h2>Order total</h2><p><span>Subtotal</span><strong>₹<?=number_format($o['subtotal'],2)?></strong></p><p><span>Delivery</span><strong>₹<?=number_format($o['delivery_fee'],2)?></strong></p><hr><p class="total"><span>Total</span><strong>₹<?=number_format($o['total'],2)?></strong></p><p><span>Payment</span><strong><?=e($o['payment_method'])?></strong></p><p><span>Payment status</span><span class="badge <?=e($o['payment_status'])?>"><?=e(ucfirst($o['payment_status']))?></span></p><p><?=e(ucfirst($o['delivery_type']))?><?= $o['delivery_address']?' to '.e($o['delivery_address']):''?></p><?php if($o['status']==='Pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="cancel"><button class="danger" data-confirm="Cancel this order?">Cancel order</button></form><?php endif;?></aside></div><?php require 'includes/footer.php'; ?>
